import type { ReactNode } from "react";
import { ThemeProvider } from "@qingye_lab/ui/components/theme-provider";
import { UILocaleProvider } from "@qingye_lab/ui/locale";

/** Include one documented CSS path in the app entry. */
export function QingyeProvider({ children }: { children: ReactNode }) {
  return <ThemeProvider><UILocaleProvider>{children}</UILocaleProvider></ThemeProvider>;
}

import { Button } from "@qingye_lab/ui/components/button";
import { Field, FieldLabel, FieldError } from "@qingye_lab/ui/components/field";
import { Input } from "@qingye_lab/ui/components/input";

/** Project composition. The application owns the draft and save result. */
export function ResourceEditor({ title, onTitleChange, onSave, saving = false, error }: { title: string; onTitleChange: (value: string) => void; onSave: () => void; saving?: boolean; error?: string }) {
  return <form onSubmit={(event) => { event.preventDefault(); onSave(); }}><Field><FieldLabel>Resource name</FieldLabel><Input value={title} onValueChange={onTitleChange} aria-invalid={Boolean(error)} />{error && <FieldError>{error}</FieldError>}</Field><Button type="submit" loading={saving}>Save draft</Button></form>;
}

/* Project-owned theme. Shared foundation components stay in @qingye_lab/ui. */
html[data-brand="project"] {
  /* Override paired roles after checking foreground/background contrast. */
}
